package com.example.highpaid.model;

import jakarta.persistence.*;
import java.math.BigDecimal;

@Entity
@Table(name = "employees")
public class Employee {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "emp_id", nullable = false, unique = true, length = 6)
    private String empId;

    @Column(name = "emp_name", nullable = false, length = 30)
    private String empName;

    @Column(name = "emp_salary", nullable = false, precision = 9, scale = 2)
    private BigDecimal empSalary;

    @Column(name = "emp_department", length = 10)
    private String empDepartment;

    // --- Constructors ---
    public Employee() {}

    public Employee(String empId, String empName, BigDecimal empSalary, String empDepartment) {
        this.empId = empId;
        this.empName = empName;
        this.empSalary = empSalary;
        this.empDepartment = empDepartment;
    }

    // --- Getters & Setters ---
    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }

    public String getEmpId() { return empId; }
    public void setEmpId(String empId) { this.empId = empId; }

    public String getEmpName() { return empName; }
    public void setEmpName(String empName) { this.empName = empName; }

    public BigDecimal getEmpSalary() { return empSalary; }
    public void setEmpSalary(BigDecimal empSalary) { this.empSalary = empSalary; }

    public String getEmpDepartment() { return empDepartment; }
    public void setEmpDepartment(String empDepartment) { this.empDepartment = empDepartment; }

    @Override
    public String toString() {
        return String.format("%-6s %-30s %9.2f %-10s",
                empId, empName, empSalary, empDepartment);
    }
}

