package com.example.highpaid.model;

import jakarta.persistence.*;
import java.math.BigDecimal;
import java.time.LocalDateTime;

/**
 * Persisted output record mirroring the COBOL OUT-RECORD (PIC X(54)).
 * Also written to high_earners.dat by the export service.
 */
@Entity
@Table(name = "high_earners")
public class HighEarnerRecord {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "emp_id", nullable = false, length = 6)
    private String empId;

    @Column(name = "emp_name", nullable = false, length = 30)
    private String empName;

    @Column(name = "emp_salary", nullable = false, precision = 9, scale = 2)
    private BigDecimal empSalary;

    @Column(name = "emp_department", length = 10)
    private String empDepartment;

    @Column(name = "batch_run_at")
    private LocalDateTime batchRunAt;

    // --- Constructors ---
    public HighEarnerRecord() {}

    public HighEarnerRecord(Employee emp, LocalDateTime batchRunAt) {
        this.empId = emp.getEmpId();
        this.empName = emp.getEmpName();
        this.empSalary = emp.getEmpSalary();
        this.empDepartment = emp.getEmpDepartment();
        this.batchRunAt = batchRunAt;
    }

    // --- Getters & Setters ---
    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }

    public String getEmpId() { return empId; }
    public void setEmpId(String empId) { this.empId = empId; }

    public String getEmpName() { return empName; }
    public void setEmpName(String empName) { this.empName = empName; }

    public BigDecimal getEmpSalary() { return empSalary; }
    public void setEmpSalary(BigDecimal empSalary) { this.empSalary = empSalary; }

    public String getEmpDepartment() { return empDepartment; }
    public void setEmpDepartment(String empDepartment) { this.empDepartment = empDepartment; }

    public LocalDateTime getBatchRunAt() { return batchRunAt; }
    public void setBatchRunAt(LocalDateTime batchRunAt) { this.batchRunAt = batchRunAt; }

    /**
     * Produces a 54-character fixed-width string matching COBOL OUT-RECORD PIC X(54).
     * Layout: EMP-ID(6) + SPACE(1) + EMP-NAME(30) + SPACE(1) + EMP-SALARY(9.2) + SPACE(1) + DEPT(10) = 58 chars -> truncated to 54
     * Actual layout mirrors EMPREC copybook: ID(6) NAME(30) SALARY(9.2) DEPT(10) = 55 raw; padded/truncated to 54.
     */
    public String toFixedWidthRecord() {
        String line = String.format("%-6s%-30s%09.2f%-10s",
                empId, empName, empSalary, empDepartment);
        // Ensure exactly 54 characters (pad or truncate) to match PIC X(54)
        if (line.length() > 54) {
            return line.substring(0, 54);
        }
        return String.format("%-54s", line);
    }
}

