package com.example.highpaid.repository;

import com.example.highpaid.model.Employee;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import org.springframework.stereotype.Repository;

import java.math.BigDecimal;
import java.util.stream.Stream;

@Repository
public interface EmployeeRepository extends JpaRepository<Employee, Long> {

    /**
     * Streams ALL employee records ordered by empId (mirrors sequential file read).
     * The caller is responsible for opening a transaction so the cursor stays open.
     */
    @Query("SELECT e FROM Employee e ORDER BY e.empId")
    Stream<Employee> streamAllOrderByEmpId();

    /**
     * Count of employees whose salary strictly exceeds the given threshold.
     * Mirrors the COBOL: IF EMP-SALARY > WS-THRESHOLD.
     */
    long countByEmpSalaryGreaterThan(BigDecimal threshold);

    /**
     * Count of all employees (mirrors WS-READ).
     */
    @Query("SELECT COUNT(e) FROM Employee e")
    long countAll();
}

