    /** Mirrors WS-THRESHOLD PIC 9(07)V99 VALUE 60000.00 */
    private BigDecimal salaryThreshold = new BigDecimal("60000.00");

    /** Output file path. Mirrors OUT-FILE ASSIGN TO "data/output/high_earners.dat" */
    private String outputFilePath = "data/output/high_earners.dat";

    public BigDecimal getSalaryThreshold() { return salaryThreshold; }
    public void setSalaryThreshold(BigDecimal salaryThreshold) { this.salaryThreshold = salaryThreshold; }

