package com.example.highpaid.service;

import com.example.highpaid.config.HighpaidProperties;
import com.example.highpaid.model.Employee;
import com.example.highpaid.model.HighEarnerRecord;
import com.example.highpaid.repository.EmployeeRepository;
import com.example.highpaid.repository.HighEarnerRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.io.BufferedWriter;
import java.io.IOException;
import java.math.BigDecimal;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.time.LocalDateTime;
import java.util.stream.Stream;

/**
 * Business logic equivalent of COBOL program HIGHPAID.
 *
 * Faithful mapping:
 *   OPEN INPUT EMP-FILE OUTPUT OUT-FILE  -> openResources()
 *   PERFORM UNTIL END-OF-FILE            -> streamAllOrderByEmpId() cursor
 *     READ EMP-FILE / AT END             -> Stream exhaustion
 *     ADD 1 TO WS-READ                   -> wsRead++
 *     IF EMP-SALARY > WS-THRESHOLD       -> emp.getEmpSalary().compareTo(threshold) > 0
 *       ADD 1 TO WS-SELECTED             -> wsSelected++
 *       WRITE OUT-RECORD FROM EMP-RECORD -> writer.write() + highEarnerRepository.save()
 *   CLOSE EMP-FILE OUT-FILE             -> stream.close() / writer.close()
 *   DISPLAY "HIGHPAID: ..."             -> log.info()
 */
@Service
public class HighPaidService {

    private static final Logger log = LoggerFactory.getLogger(HighPaidService.class);

    private final EmployeeRepository employeeRepository;
    private final HighEarnerRepository highEarnerRepository;
    private final HighpaidProperties properties;

    public HighPaidService(EmployeeRepository employeeRepository,
                           HighEarnerRepository highEarnerRepository,
                           HighpaidProperties properties) {
        this.employeeRepository = employeeRepository;
        this.highEarnerRepository = highEarnerRepository;
        this.properties = properties;
    }

    /**
     * Main processing method – direct equivalent of MAIN-PARA in COBOL.
     *
     * @return BatchResult containing wsRead and wsSelected counters.
     */
    @Transactional
    public BatchResult execute() {
        final BigDecimal wsThreshold = properties.getSalaryThreshold(); // WS-THRESHOLD VALUE 60000.00
        final LocalDateTime batchRunAt = LocalDateTime.now();

        // --- Mirrors: OPEN OUTPUT OUT-FILE (purge previous batch output) ---
        highEarnerRepository.deleteAllRecords();

        // Prepare output flat file (mirrors OPEN OUTPUT OUT-FILE)
        Path outputPath = Paths.get(properties.getOutputFilePath());
        ensureDirectoryExists(outputPath);

        int wsRead = 0;      // WS-READ     PIC 9(03) VALUE 0
        int wsSelected = 0;  // WS-SELECTED PIC 9(03) VALUE 0

        // OPEN INPUT EMP-FILE + OPEN OUTPUT OUT-FILE
        try (Stream<Employee> empStream = employeeRepository.streamAllOrderByEmpId();
             BufferedWriter writer = Files.newBufferedWriter(outputPath)) {

            // PERFORM UNTIL END-OF-FILE (stream terminates when cursor is exhausted)
            for (Employee emp : (Iterable<Employee>) empStream::iterator) {

                // NOT AT END -> ADD 1 TO WS-READ
                wsRead++;

                // IF EMP-SALARY > WS-THRESHOLD
                if (emp.getEmpSalary().compareTo(wsThreshold) > 0) {

                    // ADD 1 TO WS-SELECTED
                    wsSelected++;

                    // WRITE OUT-RECORD FROM EMP-RECORD  (flat file)
                    HighEarnerRecord record = new HighEarnerRecord(emp, batchRunAt);
                    writer.write(record.toFixedWidthRecord());
                    writer.newLine();

                    // Also persist to PostgreSQL high_earners table
                    highEarnerRepository.save(record);
                }
                // END-IF
            }
            // CLOSE EMP-FILE OUT-FILE  -> implicit via try-with-resources

        } catch (IOException e) {
            throw new HighPaidProcessingException(
                    "Failed to write output file: " + outputPath, e);
        }

        // DISPLAY "HIGHPAID: " WS-SELECTED " OF " WS-READ " RECORDS SELECTED"
        log.info("HIGHPAID: {} OF {} RECORDS SELECTED", wsSelected, wsRead);

        return new BatchResult(wsRead, wsSelected);
    }

    // ----------------------------------------------------------------
    // Private helpers
    // ----------------------------------------------------------------

    private void ensureDirectoryExists(Path filePath) {
        Path parent = filePath.getParent();
        if (parent != null) {
            try {
                Files.createDirectories(parent);
            } catch (IOException e) {
                throw new HighPaidProcessingException(
                        "Cannot create output directory: " + parent, e);
            }
        }
    }

    // ----------------------------------------------------------------
    // Inner value types
    // ----------------------------------------------------------------

    /**
     * Immutable result container – carries WS-READ and WS-SELECTED.
     */
    public static final class BatchResult {
        private final int wsRead;      // total records read
        private final int wsSelected;  // records selected (salary > threshold)

        public BatchResult(int wsRead, int wsSelected) {
            this.wsRead = wsRead;
            this.wsSelected = wsSelected;
        }

        public int getWsRead()     { return wsRead; }
        public int getWsSelected() { return wsSelected; }

        @Override
        public String toString() {
            return String.format("BatchResult{wsRead=%d, wsSelected=%d}", wsRead, wsSelected);
        }
    }
}

