package com.example.highpaid.service;

/**
 * Unchecked exception wrapping any I/O or data-access failure in the
 * HIGHPAID batch – equivalent to an abnormal STOP RUN in COBOL.
 */
public class HighPaidProcessingException extends RuntimeException {

    public HighPaidProcessingException(String message) {
        super(message);
    }

    public HighPaidProcessingException(String message, Throwable cause) {
        super(message, cause);
    }
}

