package com.example.highpaid.batch;

import com.example.highpaid.service.HighPaidService;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.boot.ApplicationArguments;
import org.springframework.boot.ApplicationRunner;
import org.springframework.stereotype.Component;

/**
 * ApplicationRunner acts as the COBOL JCL / batch entry point.
 * Spring Boot calls run() immediately after the application context is ready,
 * mirroring the top-level MAIN-PARA / STOP RUN lifecycle.
 */
@Component
public class HighPaidJobConfig implements ApplicationRunner {

    private static final Logger log = LoggerFactory.getLogger(HighPaidJobConfig.class);

    private final HighPaidService highPaidService;

    public HighPaidJobConfig(HighPaidService highPaidService) {
        this.highPaidService = highPaidService;
    }

    @Override
    public void run(ApplicationArguments args) {
        log.info("HIGHPAID batch job starting");
        HighPaidService.BatchResult result = highPaidService.execute();
        log.info("HIGHPAID batch job complete – {}", result);
    }
}

