package com.example.highpaid.controller;

import com.example.highpaid.service.HighPaidService;
import com.example.highpaid.service.HighPaidService.BatchResult;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import java.util.Map;

/**
 * REST endpoint allowing on-demand triggering of the HIGHPAID batch logic.
 * POST /api/highpaid/run  ->  executes the full extract and returns counters.
 */
@RestController
@RequestMapping("/api/highpaid")
public class HighPaidController {

    private final HighPaidService highPaidService;

    public HighPaidController(HighPaidService highPaidService) {
        this.highPaidService = highPaidService;
    }

    @PostMapping("/run")
    public ResponseEntity<Map<String, Object>> run() {
        BatchResult result = highPaidService.execute();
        Map<String, Object> body = Map.of(
                "message",     String.format("HIGHPAID: %d OF %d RECORDS SELECTED",
                                             result.getWsSelected(), result.getWsRead()),
                "wsRead",      result.getWsRead(),
                "wsSelected",  result.getWsSelected()
        );
        return ResponseEntity.ok(body);
    }
}

