package com.example.highpaid;

import com.example.highpaid.model.Employee;
import com.example.highpaid.repository.EmployeeRepository;
import com.example.highpaid.repository.HighEarnerRepository;
import com.example.highpaid.service.HighPaidService;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.context.DynamicPropertyRegistry;
import org.springframework.test.context.DynamicPropertySource;
import org.testcontainers.containers.PostgreSQLContainer;
import org.testcontainers.junit.jupiter.Container;
import org.testcontainers.junit.jupiter.Testcontainers;

import java.math.BigDecimal;
import java.util.List;

import static org.assertj.core.api.Assertions.assertThat;

@Testcontainers
@SpringBootTest
class HighPaidServiceIntegrationTest {

    @Container
    static PostgreSQLContainer<?> postgres =
            new PostgreSQLContainer<>("postgres:16-alpine")
                    .withDatabaseName("highpaid_test")
                    .withUsername("test")
                    .withPassword("test");

    @DynamicPropertySource
    static void configureDataSource(DynamicPropertyRegistry registry) {
        registry.add("spring.datasource.url",      postgres::getJdbcUrl);
        registry.add("spring.datasource.username", postgres::getUsername);
        registry.add("spring.datasource.password", postgres::getPassword);
    }

    @Autowired EmployeeRepository   employeeRepository;
    @Autowired HighEarnerRepository highEarnerRepository;
    @Autowired HighPaidService      highPaidService;

    @BeforeEach
    void setUp() {
        highEarnerRepository.deleteAllRecords();
        employeeRepository.deleteAll();

        employeeRepository.saveAll(List.of(
                new Employee("E00001", "Alice Smith",   new BigDecimal("75000.00"), "FINANCE"),
                new Employee("E00002", "Bob Jones",     new BigDecimal("45000.00"), "IT"),
                new Employee("E00003", "Carol Williams",new BigDecimal("60000.00"), "HR"),   // equal – NOT selected
                new Employee("E00004", "Dave Brown",    new BigDecimal("60000.01"), "SALES"),// just above
                new Employee("E00005", "Eve Davis",     new BigDecimal("120000.00"),"EXEC")
        ));
    }

    @Test
    void shouldSelectOnlyEmployeesEarningStrictlyAboveThreshold() {
        // COBOL: IF EMP-SALARY > WS-THRESHOLD (strictly greater than 60000.00)
        HighPaidService.BatchResult result = highPaidService.execute();

        assertThat(result.getWsRead()).isEqualTo(5);     // all 5 records read
        assertThat(result.getWsSelected()).isEqualTo(3); // Alice, Dave, Eve

        assertThat(highEarnerRepository.findAll())
                .hasSize(3)
                .extracting(h -> h.getEmpId().strip())
                .containsExactlyInAnyOrder("E00001", "E00004", "E00005");
    }

    @Test
    void shouldProduceFixedWidthRecordOf54Characters() {
        highPaidService.execute();
        highEarnerRepository.findAll().forEach(r ->
                assertThat(r.toFixedWidthRecord()).hasSize(54)
        );
    }
}
